#include "maps_submenu.h"
#include "ui_draw.h"
#include <string.h>
#define DG 0x4d2c0u
static const char*label(int layer,int row){return layer==4?(row?"Population Growth":"Population Density"):(row?"Fire":"Police");}
int sim_maps_submenu_open(const uint8_t*m,size_t n,unsigned layer,int x,int y,SimMapsSubmenu*p){int d;if(!m||n<1048576u||!p||(layer!=4&&layer!=9))return 0;memset(p,0,sizeof(*p));p->layer=(int)layer;p->current=m[DG+(layer==4?0x326c:0x326a)];p->selected=-1;p->width=(int)strlen(label((int)layer,0))+1;p->x0=(x&~7)+16;p->y0=y-11;p->x1=p->x0+p->width*8+15;if(p->x1>319){d=p->x1-319;p->x0-=d;p->x1-=d;}if(p->y0<13)p->y0=13;p->y1=p->y0+21;if(p->y1>194){d=p->y1-194;p->y0-=d;p->y1-=d;}p->text_x=p->x0+8;p->text_y=p->y0+3;return p->x0>=0&&p->y0>=0;}
int sim_maps_submenu_render(uint8_t*fb,const uint8_t*font,const SimMapsSubmenu*p){int i,good;char line[32];if(!fb||!font||!p||(p->layer!=4&&p->layer!=9)||p->width<1||p->width>=32)return 0;good=sim_ui_frame(fb,p->text_x,p->text_y,p->text_x+p->width*8-1,p->text_y+15,-3,1)&&sim_ui_frame(fb,p->text_x,p->text_y,p->text_x+p->width*8-1,p->text_y+15,-1,11);for(i=0;i<2;++i){size_t n=strlen(label(p->layer,i));memset(line,32,(size_t)p->width);line[0]=(char)(p->current==i+1?16:32);memcpy(line+1,label(p->layer,i),n);line[p->width]=0;good=good&&sim_ui_text(fb,font,p->text_x,p->text_y+i*8,line,(uint8_t)(p->selected==i?11:1),(uint8_t)(p->selected==i?1:11));}return good;}
int sim_maps_submenu_hit(const SimMapsSubmenu*p,int x,int y){if(!p||x<p->text_x||x>=p->text_x+p->width*8||y<p->text_y||y>=p->text_y+16)return -1;return (y-p->text_y)/8;}
int sim_maps_submenu_key(SimMapsSubmenu*p,unsigned k){int i,j;if(!p)return 0;if(k==27){p->selected=-1;return 1;}if(k==10||k==13||k==32||k==0x852||k==0x853)return 1;if(k=='+'||k==0x850)p->selected=(p->selected+1)%2;else if(k=='-'||k==0x848)p->selected=p->selected>0?p->selected-1:1;else{if(k&0x800u){p->selected=-1;return 2;}if(k>='a'&&k<='z')k-=32;for(i=1;i<=2;++i){unsigned c=(unsigned char)label(p->layer,j=(p->selected+i+2)%2)[1];if(c>='a'&&c<='z')c-=32;if(c==k){p->selected=j;break;}}}return 0;}
int sim_maps_submenu_commit(uint8_t*m,size_t n,const SimMapsSubmenu*p){unsigned o;int v;if(!m||n<1048576u||!p||(p->layer!=4&&p->layer!=9))return 0;o=p->layer==4?0x326c:0x326a;v=p->selected>=0&&p->selected<2?p->selected+1:p->current;m[DG+o]=(uint8_t)v;m[DG+o+1]=0;m[DG+0x3268]=(uint8_t)p->layer;m[DG+0x3269]=0;return 1;}
